ther bare or with a trailing ": " separator; match on the code itself and tolerate the separator.","example":"900900","pattern":"^(ABDM-\d{4}|\d{3,6})(: )?$","type":"string"},"description":{"example":"Access failure for API: /hiecm/api/v3, version: v3 status: (900900) - Unclassified Authentication Failure","type":"string"},"message":{"example":"Unclassified Authentication Failure","type":"string"}},"type":"object"}}},"description":"Internal Server Error"},"503":{"content":{"application/json":{"schema":{"properties":{"code":{"description":"ABDM-1024 - Dependent service unavailable. May be returned either bare (`ABDM-1024`) or with a trailing ": " separator (`ABDM-1024: `); match on the code itself and tolerate the separator.","example":"ABDM-1024","pattern":"^(ABDM-\d{4}|\d{3,6})(: )?$","type":"string"},"message":{"example":"Dependent service unavailable","type":"string"}},"required":["code","message"],"type":"object"}}},"description":"Service Unavailable"}},"security":[{"bearerAuth":[]}],"summary":"Health information data request from HIU.","tags":["consent-management-data-flow-hiu"],"x-abdm-nha-operation-id":"abdm-data-flow 7"}}
